import AppKit

#if FRAMEJOB_DEV_TOOLS
/// `tutorial_start`, `tutorial_state`, `tutorial_step` and `tutorial_exit` —
/// dev tools (spec §11 TU-8, V-1..V-2): drive a project window's tutorial
/// runner (`TutorialRunner`) with no chrome, so `tutorial_proof.py` can run
/// the guide's tutorials as a person and by Show Me alone. The product's door
/// is TU3's coach panel and Help ▸ Tutorials.
///
/// Every answer but a refusal is the runner's state, `{ok, project,
/// running}` and, while one runs, `TutorialRunner.state()`. A refusal — no
/// editor window, an unknown or refused id, unmet needs, a move the step does
/// not offer — is the runner's own sentence.
///
/// `tutorial_start`, `tutorial_state` and `tutorial_exit` run on MAIN.
/// `tutorial_start`'s answer is made in its own main block, so it shows step
/// 1; the start's evaluation runs on a later main turn, before any later
/// tool's main block (the main queue is first in, first out).
/// `tutorial_step` runs on the SERVER thread (`devOffMainTools`): `show_me`
/// presses Show Me on main, then waits WITHOUT the lane's lock
/// (`AgentLane.releasingLock`, as `assistant_send` does), reading the
/// runner on main every 50 ms for up to 60 s, because Show Me's own calls go
/// through the lane's `submit` and need the lock.
extension AgentServer {

    func tutorialStart(_ a: [String: Any]) throws -> String {
        guard let id = try stringArg(a, "id") else {
            throw ToolError(message: "Missing required argument: id")
        }
        let (editor, project) = try tutorialEditor(a)
        let library: TutorialLibrary
        do {
            library = try TutorialLibrary.bundled()
        } catch {
            throw ToolError(message: error.localizedDescription)
        }
        if let reason = library.refused[id] {
            throw ToolError(message: "The tutorial \(id) does not read: \(reason).")
        }
        guard let tutorial = library.tutorial(id: id) else {
            throw ToolError(
                message: "No tutorial is called \(id); the tutorials are "
                    + library.ids.joined(separator: ", ") + ".")
        }
        do {
            try TutorialRunner.start(tutorial, in: editor)
        } catch let refusal as TutorialRefusal {
            throw ToolError(message: refusal.sentence)
        }
        return try jsonResult(Self.tutorialAnswer(editor, project))
    }

    func tutorialState(_ a: [String: Any]) throws -> String {
        let (editor, project) = try tutorialEditor(a)
        return try jsonResult(Self.tutorialAnswer(editor, project))
    }

    func tutorialExit(_ a: [String: Any]) throws -> String {
        let (editor, project) = try tutorialEditor(a)
        guard let runner = editor.tutorialRunner else {
            throw ToolError(message: Self.noTutorial)
        }
        runner.exit()
        return try jsonResult(Self.tutorialAnswer(editor, project))
    }

    func tutorialStep(_ a: [String: Any]) throws -> String {
        guard let action = try stringArg(a, "action") else {
            throw ToolError(message: "Missing required argument: action")
        }
        guard Self.tutorialActions.contains(action) else {
            throw ToolError(
                message: "action must be show_me, next, back or skip (got \"\(action)\").")
        }
        // This thread holds the editor and the runner only weakly, so it never
        // keeps either alive past an exit or a start while the lock is out.
        weak var watchedEditor: EditorViewController?
        weak var watchedRunner: TutorialRunner?
        let project = try onMain { () throws -> Any in
            let (editor, project) = try self.tutorialEditor(a)
            guard let runner = editor.tutorialRunner else {
                throw ToolError(message: Self.noTutorial)
            }
            do {
                switch action {
                case "show_me": try runner.showMe()
                case "next": try runner.next()
                case "back": try runner.back()
                default: try runner.skip()
                }
            } catch let refusal as TutorialRefusal {
                throw ToolError(message: refusal.sentence)
            }
            watchedEditor = editor
            watchedRunner = runner
            return project
        }
        if action == "show_me" {
            let started = Date()
            AgentLane.shared.releasingLock {
                while Date().timeIntervalSince(started) < Self.showMeTimeout {
                    let running = onMain { () -> Bool in
                        guard let editor = watchedEditor, let runner = watchedRunner else {
                            return false
                        }
                        return editor.tutorialRunner === runner && runner.showMeRunning
                    }
                    guard running else { break }
                    Thread.sleep(forTimeInterval: 0.05)
                }
            }
        }
        return try jsonResult(
            onMain { () throws -> [String: Any] in
                let (editor, _) = try self.tutorialEditor(a)
                return Self.tutorialAnswer(editor, project)
            })
    }

    private static let tutorialActions: Set<String> = ["show_me", "next", "back", "skip"]
    private static let showMeTimeout = 60.0
    private static let noTutorial =
        "No tutorial is running in this window: tutorial_start starts one."

    /// The project's editor and its path for the answer, refused as
    /// `select_inspector_tab` refuses a windowless project. Main thread.
    private func tutorialEditor(_ a: [String: Any]) throws -> (EditorViewController, Any) {
        let document = try target(a)
        guard let editor = editor(document), editor.isViewLoaded else {
            let name = Self.path(of: document) ?? document.displayName ?? "Untitled"
            throw ToolError(
                message: "The project \(name) has no window: a tutorial runs only in its editor "
                    + "window.")
        }
        return (editor, UISnapshot.orNull(Self.path(of: document)))
    }

    /// The state every tool answers. Main thread.
    private static func tutorialAnswer(_ editor: EditorViewController, _ project: Any)
        -> [String: Any] {
        var answer: [String: Any] = ["ok": true, "project": project, "running": false]
        if let runner = editor.tutorialRunner {
            answer.merge(runner.state()) { _, theirs in theirs }
        }
        return answer
    }

    // MARK: - Catalog

    func tutorialStartTool() -> [String: Any] {
        tool(
            "tutorial_start",
            "DEV TOOL (absent from Distribution builds). Start a guide tutorial by id in a "
                + "project's editor window, replacing any tutorial running there: its needs are "
                + "checked first and, when no clip meets them, the call is refused with the "
                + "sentence naming what is missing. Answers the runner's state at step 1: ok, "
                + "project, running and, while running, id, title, step (1-based), steps, text, "
                + "optional, wait, show_me, offers (of back, show_me, skip, next, exit), "
                + "spotlight, reveal {tab, sub_tab, section} or null, reveal_refused, finished, "
                + "show_me_running, last_show_me {step, ok, error, results, paths} or null, "
                + "selection_at_start, created and completed [{step, by}]. A wait already met "
                + "advances on a later main turn. Refused: an unknown id (the refusal lists the "
                + "tutorials), a tutorial the model does not read (with its reason) and a project "
                + "with no window.",
            [
                "id": [
                    "type": "string",
                    "description": "The tutorial's id, as its guide page names it "
                        + "(audio.volume, editing.split, …).",
                ]
            ],
            required: ["id"])
    }

    func tutorialStateTool() -> [String: Any] {
        tool(
            "tutorial_state",
            "DEV TOOL (absent from Distribution builds). Answer the state of the tutorial "
                + "running in a project's editor window, changing nothing: running false when "
                + "none runs, else the fields tutorial_start answers.",
            [:])
    }

    func tutorialStepTool() -> [String: Any] {
        tool(
            "tutorial_step",
            "DEV TOOL (absent from Distribution builds). Press one of the running tutorial's "
                + "buttons: show_me runs the step's Show Me — its tool calls through the "
                + "assistant's lane with ordinary undo, its menu items through the menu bar's "
                + "own validated item — and answers once it has finished (up to 60 s), its "
                + "outcome in last_show_me; next goes on from a step with no wait; back re-begins "
                + "the step before (or the last, once finished) and does not evaluate it; skip "
                + "passes an optional step. Answers the state. Refused in the runner's own "
                + "sentence: a move the step does not offer, and no tutorial running.",
            [
                "action": [
                    "type": "string", "enum": ["show_me", "next", "back", "skip"],
                    "description": "The button: show_me, next, back or skip.",
                ]
            ],
            required: ["action"])
    }

    func tutorialExitTool() -> [String: Any] {
        tool(
            "tutorial_exit",
            "DEV TOOL (absent from Distribution builds). End the tutorial running in a "
                + "project's editor window, undoing nothing. Answers the state (running false). "
                + "Refused when no tutorial runs there.",
            [:])
    }
}
#endif

import AppKit

/// The Assistant tab's question dot (spec §11 AI-19): a small accent-coloured
/// dot just right of "Assistant" in the inspector's tab strip, shown while
/// the window's assistant waits on an ask-first question, whichever tab is
/// showing.
///
/// Its own view laid over the strip rather than a fork of `PanelTabsView`
/// (`Controls.swift` is carried from Rasterize and kept in sync), so it
/// mirrors `PanelTabsView.tabRect`'s arithmetic and the way the strip centres
/// a title, as `ClipSubTabsView.cellRect` does. It is the inspector root's
/// LAST subview, above the container `buildTabs()` refills on every tab
/// change. Passive: it takes no click (`hitTest` answers nil, so a click
/// reaches the strip) and no key.
final class InspectorTabBadge: NSView {
    static let identifier = "inspector.assistant.badge"
    static let diameter: CGFloat = 6
    static let gap: CGFloat = 3

    init() {
        super.init(frame: .zero)
        isHidden = true
        translatesAutoresizingMaskIntoConstraints = false
        setAccessibilityIdentifier(Self.identifier)
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("InspectorTabBadge does not support NSCoder")
    }

    override var isFlipped: Bool { true }

    override func hitTest(_ point: NSPoint) -> NSView? { nil }

    override func setFrameSize(_ newSize: NSSize) {
        super.setFrameSize(newSize)
        needsDisplay = true
    }

    override func draw(_ dirtyRect: NSRect) {
        DS.accent.setFill()
        NSBezierPath(
            ovalIn: Self.dotRect(stripWidth: bounds.width, stripHeight: bounds.height)
        ).fill()
    }

    /// Added to `root` with its four edges on `strip`'s.
    func install(over strip: NSView, in root: NSView) {
        root.addSubview(self)
        NSLayoutConstraint.activate([
            topAnchor.constraint(equalTo: strip.topAnchor),
            bottomAnchor.constraint(equalTo: strip.bottomAnchor),
            leadingAnchor.constraint(equalTo: strip.leadingAnchor),
            trailingAnchor.constraint(equalTo: strip.trailingAnchor),
        ])
    }

    /// `PanelTabsView.tabRect`'s arithmetic (equal widths, `.rounded()`
    /// edges) for the Assistant tab of `InspectorTab.allCases.count`.
    static func tabRect(stripWidth: CGFloat, stripHeight: CGFloat) -> NSRect {
        let index = InspectorTab.assistant.rawValue
        let width = stripWidth / CGFloat(max(InspectorTab.allCases.count, 1))
        let left = (CGFloat(index) * width).rounded()
        let right = (CGFloat(index + 1) * width).rounded()
        return NSRect(x: left, y: 0, width: right - left, height: stripHeight)
    }

    /// The Assistant title in the active tab's font, centred in `tabRect`
    /// exactly as `PanelTabsView` draws a title. The semibold face is the
    /// wider of the strip's two, so the dot clears the word either way.
    static func titleRect(stripWidth: CGFloat, stripHeight: CGFloat) -> NSRect {
        let tab = tabRect(stripWidth: stripWidth, stripHeight: stripHeight)
        let size = InspectorTab.assistant.title.size(
            withAttributes: [.font: DS.sans(12, weight: .semibold)])
        return NSRect(
            x: tab.midX - size.width / 2, y: tab.midY - size.height / 2,
            width: size.width, height: size.height)
    }

    /// Just right of the title, never past the tab's trailing edge less 2 pt.
    static func dotRect(stripWidth: CGFloat, stripHeight: CGFloat) -> NSRect {
        let tab = tabRect(stripWidth: stripWidth, stripHeight: stripHeight)
        let title = titleRect(stripWidth: stripWidth, stripHeight: stripHeight)
        let x = min(title.maxX + gap, tab.maxX - 2 - diameter).rounded()
        let y = (tab.midY - diameter / 2).rounded()
        return NSRect(x: x, y: y, width: diameter, height: diameter)
    }
}

extension InspectorViewController {
    /// The editor's forward from `assistantRefresh()`: the dot while a
    /// question waits.
    func showAssistantBadge(_ shown: Bool) {
        assistantBadge.isHidden = !shown
    }
}

import AppKit

#if FRAMEJOB_DEV_TOOLS
/// `snapshot_ui`'s main-thread half (road map 11's V2a, spec §11 V-1..V-3):
/// which window and which view a call means, the facts about that window,
/// the temporary staging a capture needs, and one `cacheDisplay` pass.
///
/// Every member is main-thread only. The handler
/// (`AgentServer+Snapshot.swift`) runs on the server thread and reaches each
/// one through `onMain`, one hop per pass, so the settle loop's waits are
/// the server's and the main run loop turns freely between passes.
///
/// **Staging is undone on every exit.** The fill is an `NSImageView` put
/// just above `playerHost` — under `safeGuides` and `overlay`, V1's W4a — so
/// the handles land on the picture as they do on screen. It comes out again
/// in `unstage`, which the handler calls from a `defer`: left in, the next
/// capture differs (V1's W6). No appearance is staged: a live switch left
/// build-time colours in the launch appearance (V3), so the look is the
/// instance's, chosen at launch (`DevAppearance`).
enum UISnapshot {
    enum WindowKind: String, CaseIterable {
        case editor, sheet, settings, welcome, recorder

        /// The window's name in a refusal.
        var title: String {
            switch self {
            case .editor: return "editor"
            case .sheet: return "sheet"
            case .settings: return "Settings"
            case .welcome: return "Welcome"
            case .recorder: return "New Recording"
            }
        }
    }
    enum Region: String, CaseIterable { case toolbar, preview, inspector, timeline }

    /// What one capture is of: the window, the view drawn into the PNG, and
    /// the editor behind it when there is one (the fill and the regions).
    struct Subject {
        let window: NSWindow
        let root: NSView
        let kind: WindowKind
        let region: Region?
        let editor: EditorViewController?
    }

    /// One `cacheDisplay` of a root: the bitmap and a copy of its bytes, which
    /// is what two passes are compared by.
    struct Pass {
        let rep: NSBitmapImageRep
        let bytes: Data
    }

    /// What `stage` changed, so `unstage` can put it back.
    struct Staging {
        let window: NSWindow
        let fill: NSImageView?
    }

    /// `harness/main.swift`'s settle: two consecutive passes byte-identical,
    /// at most forty of them, 20 ms apart.
    static let settleLimit = 40
    static let settleInterval: TimeInterval = 0.02

    // MARK: - Resolution

    /// The open Settings, Welcome or New Recording window, found among
    /// `NSApp.windows` by its controller's class. Never `.shared`: touching
    /// any of those singletons BUILDS its window, and a capture must not open
    /// what it was asked to look at.
    static func openWindow(_ kind: WindowKind) -> NSWindow? {
        NSApp.windows.first { window in
            guard window.isVisible else { return false }
            switch kind {
            case .settings: return window.windowController is SettingsWindowController
            case .welcome: return window.windowController is WelcomeWindowController
            case .recorder: return window.windowController is RecorderPanelController
            case .editor, .sheet: return false
            }
        }
    }

    /// A named region of the editor: the toolbar is the root's `BarView`, the
    /// other three are the editor's pane containers.
    static func regionView(_ region: Region, of editor: EditorViewController) -> NSView? {
        switch region {
        case .toolbar: return editor.view.subviews.first { $0 is BarView }
        case .preview: return editor.canvasContainer
        case .inspector: return editor.inspectorContainer
        case .timeline: return editor.timelineContainer
        }
    }

    /// `view`'s bounds in `root`'s space, top-left origin, in points rounded
    /// to two decimal places: `[x, y, w, h]`.
    static func rect(_ view: NSView, in root: NSView) -> [Double] {
        let r = view.convert(view.bounds, to: root)
        let top = root.isFlipped ? r.minY : root.bounds.height - r.maxY
        return [r.minX, top, r.width, r.height].map { round2($0) }
    }

    static func round2(_ value: CGFloat) -> Double {
        (Double(value) * 100).rounded() / 100
    }

    /// A JSON value for an optional string: the string, or `null`.
    static func orNull(_ value: String?) -> Any {
        value.map { $0 as Any } ?? NSNull()
    }

    // MARK: - Facts

    /// What the capture depended on: a proof compares only captures whose
    /// scale, activity, key state and colour space agree.
    static func facts(_ window: NSWindow) -> [String: Any] {
        [
            "active": NSApp.isActive,
            "key": window.isKeyWindow,
            "main": window.isMainWindow,
            "visible": window.isVisible,
            "occluded": !window.occlusionState.contains(.visible),
            "scale": Double(window.backingScaleFactor),
            "color_space": orNull(window.colorSpace?.localizedName),
            "sheet_attached": window.attachedSheet != nil,
        ]
    }

    /// The visible windows, in `windowNumber` order, each with what a caller
    /// needs to choose one.
    static func listing() -> [String: Any] {
        let windows = NSApp.windows.filter { $0.isVisible }
            .sorted { $0.windowNumber < $1.windowNumber }
        return [
            "ok": true,
            "active": NSApp.isActive,
            "windows": windows.map(row),
        ]
    }

    static func kind(of window: NSWindow) -> String {
        if window.contentViewController is EditorViewController { return "editor" }
        if window.sheetParent != nil { return "sheet" }
        if window.windowController is SettingsWindowController { return "settings" }
        if window.windowController is WelcomeWindowController { return "welcome" }
        if window.windowController is RecorderPanelController { return "recorder" }
        if window is NSPanel { return "panel" }
        return "other"
    }

    static func row(_ window: NSWindow) -> [String: Any] {
        let frame = window.frame
        let content = window.contentView?.bounds.size ?? .zero
        var project: Any = NSNull()
        if window.contentViewController is EditorViewController,
            let document = window.windowController?.document as? ProjectDocument
        {
            project = orNull(AgentServer.path(of: document))
        }
        var sheet: Any = NSNull()
        if let attached = window.attachedSheet {
            let size = attached.contentView?.bounds.size ?? .zero
            sheet = [
                "class": NSStringFromClass(type(of: attached)),
                "content": [round2(size.width), round2(size.height)],
                "file_panel": attached is NSSavePanel,
            ] as [String: Any]
        }
        return [
            "kind": kind(of: window),
            "class": NSStringFromClass(type(of: window)),
            "title": window.title,
            "frame": [frame.minX, frame.minY, frame.width, frame.height].map { round2($0) },
            "content": [round2(content.width), round2(content.height)],
            "scale": Double(window.backingScaleFactor),
            "visible": window.isVisible,
            "occluded": !window.occlusionState.contains(.visible),
            "key": window.isKeyWindow,
            "main": window.isMainWindow,
            "project": project,
            "sheet": sheet,
        ]
    }

    // MARK: - Staging

    /// With a picture, puts it under the canvas overlay at `playerHost`'s
    /// frame (V1's W4a).
    static func stage(_ subject: Subject, picture: CGImage?) -> Staging {
        var fill: NSImageView?
        if let picture, let canvas = subject.editor?.previewCanvas {
            let host = canvas.playerHost
            let view = NSImageView(frame: host.frame)
            view.image = NSImage(
                cgImage: picture, size: NSSize(width: picture.width, height: picture.height))
            view.imageScaling = .scaleAxesIndependently
            view.imageFrameStyle = .none
            canvas.addSubview(view, positioned: .above, relativeTo: host)
            fill = view
        }
        return Staging(window: subject.window, fill: fill)
    }

    /// Takes the fill out.
    static func unstage(_ staging: Staging) {
        staging.fill?.removeFromSuperview()
    }

    // MARK: - Capture

    /// One pass: lay out, display, `cacheDisplay` the root, copy its bytes.
    static func pass(_ root: NSView) -> Pass? {
        root.layoutSubtreeIfNeeded()
        root.displayIfNeeded()
        guard let rep = root.bitmapImageRepForCachingDisplay(in: root.bounds) else { return nil }
        root.cacheDisplay(in: root.bounds, to: rep)
        guard let data = rep.bitmapData else { return nil }
        return Pass(rep: rep, bytes: Data(bytes: data, count: rep.bytesPerRow * rep.pixelsHigh))
    }
}
#endif

import AppKit

#if FRAMEJOB_DEV_TOOLS
/// `snapshot_ui` — a dev tool (road map 11's V2a, spec §11 V-1..V-3): the
/// app's windows listed, or one of them captured through `cacheDisplay` as
/// an MCP image block and a PNG on disk, with a layout dump beside it.
///
/// **It runs on the SERVER thread** (`devOffMainTools`), where the road map
/// said main: the fill waits on `Exporter.renderFrameReported`, which
/// decodes, and the settle waits 20 ms between passes, and neither may hold
/// the main thread. So every AppKit touch is an `onMain` hop — one to
/// resolve the window, one to stage, one per pass, one to read the facts and
/// the layout and unstage — and the waits are this thread's.
///
/// **It never needs the app active or its window visible**: `cacheDisplay`
/// draws the view tree, not the screen, and every fact that could change a
/// picture (`active`, `key`, `occluded`, `scale`, `color_space`) comes back
/// in `window_facts` so a comparison can refuse to compare what differs.
extension AgentServer {

    private struct SnapshotRequest {
        let window: UISnapshot.WindowKind
        let region: UISnapshot.Region?
        let url: URL
        let fill: Bool
        let layout: Bool
    }

    /// The fill's inputs, read on main in the first hop.
    private struct FillContext {
        let project: ReelProject
        let urls: [UInt32: URL]
        let playhead: Ticks
        let graphics: GraphicSet?
        let maxWidth: Int
    }

    private static let captureArguments = ["view", "path", "fill_preview", "layout"]
    private static let appearanceRefusal = "appearance is refused: switched on a live window it "
        + "left colours built in the launch appearance, a mix the app never draws. Launch the "
        + "instance with -RCDevAppearance light or -RCDevAppearance dark instead."

    func snapshotUI(_ a: [String: Any]) throws -> String {
        guard let request = try snapshotRequest(a) else {
            return try jsonResult(onMain { UISnapshot.listing() })
        }
        let (subject, context) = try onMain { try self.snapshotSubject(a, request) }

        var picture: CGImage?
        var tick: Ticks?
        if let context {
            picture = Exporter.renderFrameReported(
                project: context.project, urls: context.urls, at: context.playhead,
                maxWidth: context.maxWidth, options: .none, graphics: context.graphics
            ).image
            tick = context.playhead
        }

        var staging: UISnapshot.Staging? = onMain {
            UISnapshot.stage(subject, picture: picture)
        }
        defer {
            if let left = staging { onMain { UISnapshot.unstage(left) } }
        }

        var last: UISnapshot.Pass?
        var passes = 0
        var settled = false
        while passes < UISnapshot.settleLimit {
            guard let next = onMain({ UISnapshot.pass(subject.root) }) else {
                throw ToolError(message: "The \(request.window.rawValue) window did not draw.")
            }
            passes += 1
            if let previous = last, previous.bytes == next.bytes {
                last = next
                settled = true
                break
            }
            last = next
            Thread.sleep(forTimeInterval: UISnapshot.settleInterval)
        }
        guard let capture = last, let image = capture.rep.cgImage else {
            throw ToolError(message: "The \(request.window.rawValue) window did not draw.")
        }

        var result: [String: Any] = [:]
        var layoutReport: [String: Any]?
        var points = CGSize.zero
        onMain {
            result = self.snapshotFacts(subject, request)
            points = subject.root.bounds.size
            if request.layout {
                layoutReport = UISnapshotLayout.report(root: subject.root, skipping: staging?.fill)
            }
            if let done = staging {
                UISnapshot.unstage(done)
                staging = nil
            }
        }

        if subject.kind == .editor {
            let preview = previewState(request, filled: picture != nil, asked: context != nil)
            result["preview"] = preview.state
            result["preview_note"] = preview.note
            if picture != nil, let tick { result["preview_tick"] = tick }
        }
        do {
            try FrameWriter.write(image, as: .png, to: request.url)
        } catch {
            throw ToolError(message: error.localizedDescription)
        }
        guard let data = try? Data(contentsOf: request.url) else {
            throw ToolError(message: "Wrote \(request.url.path) but could not read it back.")
        }
        result["ok"] = true
        result["window"] = request.window.rawValue
        result["view"] = request.region?.rawValue ?? NSNull()
        result["path"] = request.url.path
        result["width_px"] = capture.rep.pixelsWide
        result["height_px"] = capture.rep.pixelsHigh
        result["points"] = [UISnapshot.round2(points.width), UISnapshot.round2(points.height)]
        result["settled"] = settled
        result["passes"] = passes
        result["layout_path"] = NSNull()
        if let layoutReport {
            let layoutURL = request.url.deletingPathExtension()
                .appendingPathExtension("layout.json")
            var file = layoutReport
            file["window"] = request.window.rawValue
            file["view"] = request.region?.rawValue ?? NSNull()
            file["scale"] = result["scale"]
            file["size"] = result["points"]
            let json = try JSONSerialization.data(
                withJSONObject: file, options: [.prettyPrinted, .sortedKeys])
            do {
                try json.write(to: layoutURL)
            } catch {
                throw ToolError(
                    message: "Could not write \(layoutURL.path): \(error.localizedDescription)")
            }
            result["layout_path"] = layoutURL.path
            result["problems"] = layoutReport["problems"] ?? []
            result["private_problems"] =
                (layoutReport["private_problems"] as? [[String: Any]])?.count ?? 0
        }
        let text = try JSONSerialization.data(withJSONObject: result, options: [.sortedKeys])
        return try callResult(
            content: [
                ["type": "image", "data": data.base64EncodedString(), "mimeType": "image/png"],
                ["type": "text", "text": String(decoding: text, as: UTF8.self)],
            ], isError: false)
    }

    // MARK: - Arguments

    /// Every argument read and refused here, off main, before any hop. nil
    /// is a listing.
    private func snapshotRequest(_ a: [String: Any]) throws -> SnapshotRequest? {
        let window = try enumArg(a, "window", UISnapshot.WindowKind.self)
        let region = try enumArg(a, "view", UISnapshot.Region.self)
        if a["appearance"] != nil { throw ToolError(message: Self.appearanceRefusal) }
        let path = try stringArg(a, "path")
        let fill = try boolArg(a, "fill_preview") ?? true
        let layout = try boolArg(a, "layout") ?? true
        let hasProject = a["project"] != nil && !(a["project"] is NSNull)
        guard let window else {
            let given = Self.captureArguments.filter { a[$0] != nil && !(a[$0] is NSNull) }
            if !given.isEmpty {
                throw ToolError(
                    message: "\(given.joined(separator: ", ")) \(given.count == 1 ? "is" : "are") "
                        + "for a capture and needs window; with no window snapshot_ui lists the "
                        + "open windows.")
            }
            if hasProject {
                throw ToolError(
                    message: "project names the editor to capture and needs window editor or "
                        + "sheet; with no window snapshot_ui lists every open window.")
            }
            return nil
        }
        if hasProject, window != .editor, window != .sheet {
            throw ToolError(
                message: "project cannot name the \(window.rawValue) window: it belongs to no "
                    + "document.")
        }
        if region != nil, window != .editor {
            throw ToolError(
                message: "view names a region of the editor and cannot be used with window "
                    + "\(window.rawValue).")
        }
        return SnapshotRequest(
            window: window, region: region,
            url: try snapshotDestination(path, window, region), fill: fill, layout: layout)
    }

    /// `render_frame`'s rule: an explicit path through `destinationURL`, its
    /// folder required to exist; none is a temporary file named for what it
    /// holds.
    private func snapshotDestination(
        _ path: String?, _ window: UISnapshot.WindowKind, _ region: UISnapshot.Region?

import Foundation

// MARK: - The dev-tools seam: tools compiled only under FRAMEJOB_DEV_TOOLS

/// Where the dev tools live (road map 11, spec §11 V-1 and V-2).
///
/// **The flag.** `FRAMEJOB_DEV_TOOLS` is a Swift compilation condition that
/// Debug and Release set and the Distribution configuration does not
/// (`project.yml`), so every proof and agent session, which launch Release,
/// has the dev tools and the binary `make dist` builds has none of their
/// code (V-1). A dev tool is an ORDINARY tool (V-2): a handler in
/// `devHandlers`, a row from `devTools()`, and nothing else — the parity
/// check, the argument gate and the schema checks cover it as they cover a
/// product tool, in both builds, because both tables are merged before any
/// of them reads.
///
/// **Why the check greps a marker, not tool names.** Swift string literals
/// of 15 UTF-8 bytes or fewer are stored inline in the code of an `-O`
/// binary, not as contiguous bytes, so a short tool name such as
/// `snapshot_ui` (11) can never be found in either build and an absence
/// check on it would pass for nothing. `tools/proof/dist_check.py` reads
/// `devToolsMarker` out of this file instead — at least 16 bytes — and
/// requires it present in Release's binary and absent from Distribution's.
///
/// **What keeps the marker live.** The flag-on `devTools()` logs it, so the
/// optimiser cannot drop the literal. V2 adds rows and handlers here with no
/// edit to the check.
///
/// **Where the rows go.** `catalogJSON()` splices `devTools()` in
/// immediately BEFORE the file tools, never at the end: the catalog's last
/// eleven names are the file group plus `record_screen`, which
/// `recording_probe.py` asserts. Swift takes no `#if` inside a dictionary
/// literal, so `AgentServer.swift` merges `devHandlers` through
/// `withDevHandlers` and `devOffMainTools` by a union, one line each.
extension AgentServer {
    typealias ToolHandler = (AgentServer) -> ([String: Any]) throws -> String

    /// `product` with `devHandlers` merged in. A dev tool that reuses a
    /// product tool's name keeps the PRODUCT handler and complains the way
    /// the startup parity check does.
    static func withDevHandlers(_ product: [String: ToolHandler]) -> [String: ToolHandler] {
        var merged = product
        for (name, handler) in devHandlers.sorted(by: { $0.key < $1.key }) {
            if merged[name] != nil {
                let msg = "dev tool \(name) reuses a product tool's name"
                assertionFailure(msg)
                NSLog("Frame Job: %@", msg)
                continue
            }
            merged[name] = handler
        }
        return merged
    }

    /// Every dev tool's name, in either build (empty in Distribution): the
    /// assistant withholds each one (spec §11 AI-7, `AssistantToolTable`).
    static var devToolNames: Set<String> { Set(devHandlers.keys) }

    #if FRAMEJOB_DEV_TOOLS
    // dist_check.py parses the next line (D1) and requires it bare — nothing after the
    // closing quote — at least 16 bytes, present in Release's binary, absent from Distribution's.
    static let devToolsMarker = "framejob-dev-tools-compiled-in"

    private static let devHandlers: [String: ToolHandler] = [
        // AgentServer+Snapshot.swift
        "snapshot_ui": { $0.snapshotUI },
        // AgentServer+MenuItem.swift
        "perform_menu_item": { $0.performMenuItem },
        "cancel_sheet": { $0.cancelSheet },
        // AgentServer+InspectorTab.swift
        "select_inspector_tab": { $0.selectInspectorTab },
        // AgentServer+Assistant.swift
        "assistant_send": { $0.assistantSend },
        "assistant_answer": { $0.assistantAnswer },
        // AgentServer+PlayPreview.swift
        "play_preview": { $0.playPreview },
        // AgentServer+GraphicMemory.swift
        "graphic_memory": { $0.graphicMemory },
        // AgentServer+Tutorials.swift
        "tutorial_start": { $0.tutorialStart },
        "tutorial_state": { $0.tutorialState },
        "tutorial_step": { $0.tutorialStep },
        "tutorial_exit": { $0.tutorialExit },
    ]

    static let devOffMainTools: Set<String> = [
        "snapshot_ui", "perform_menu_item", "cancel_sheet", "assistant_send", "assistant_answer",
        "play_preview", "graphic_memory", "tutorial_step",
    ]

    /// The dev tools' catalog rows, in catalog order: `snapshot_ui` (V2a),
    /// `perform_menu_item` and `cancel_sheet` (V2b), `select_inspector_tab`
    /// (V3), `assistant_send` and `assistant_answer` (road map 12 A1),
    /// `play_preview` (issue #127, G-36), `graphic_memory` (issue #127,
    /// G-37), `tutorial_start`, `tutorial_state`, `tutorial_step` and
    /// `tutorial_exit` (Tutorials TU2, spec §11 TU-8). The log is what keeps `devToolsMarker` in the optimised binary;
    /// it never says `Frame Job: `, the prefix a proof reads as the parity
    /// check complaining.
    func devTools() -> [[String: Any]] {
        let rows: [[String: Any]] = [
            snapshotUITool(), performMenuItemTool(), cancelSheetTool(), selectInspectorTabTool(),
            assistantSendTool(), assistantAnswerTool(), playPreviewTool(), graphicMemoryTool(),
            tutorialStartTool(), tutorialStateTool(), tutorialStepTool(), tutorialExitTool(),
        ]
        NSLog("Frame Job agent server: %@, %ld dev tools", Self.devToolsMarker, rows.count)
        return rows
    }
    #else
    private static let devHandlers: [String: ToolHandler] = [:]

    static let devOffMainTools: Set<String> = []

    /// Distribution ships no dev tools.
    func devTools() -> [[String: Any]] {
        []
    }
    #endif
}

